<script setup lang="ts">
import { ref, computed, watch, onBeforeUnmount } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import PostCard from '@/components/PostCard.vue'
import { communityApi } from '@/api/community'
import { mediaApi,socialApi } from '@/api/social'
import { useAuthStore } from '@/stores/auth'
import type { Post } from '@/types/community'
const auth=useAuthStore(),route=useRoute(),router=useRouter()
const posts=ref<Post[]>([]),loading=ref(false),error=ref(''),hasMore=ref(false),before=ref<number|null>(null),draft=ref(''),publishing=ref(false),uploading=ref(false),fileInput=ref<HTMLInputElement>(),images=ref<{id:string;url:string}[]>([]),authorName=ref('')
const authorId=computed(()=>{const id=Number(route.query.authorId);return Number.isSafeInteger(id)&&id>0?id:undefined})
const own=computed(()=>authorId.value===auth.user?.id),title=computed(()=>own.value?'我的动态':authorId.value?`${authorName.value||'TA'}的动态`:'表白墙')
let alive=true,sequence=0,epoch=0,retry:{clientRequestId:string;content:string;mediaIds:string[]}|null=null
function message(e:unknown){return e instanceof Error?e.message:'操作失败，请重试'}
async function load(older=false){const run=++sequence,generation=epoch;loading.value=true;error.value='';try{const data=await communityApi.feed(authorId.value,older?before.value||undefined:undefined);if(!alive||run!==sequence||generation!==epoch)return;const seen=new Set(posts.value.map(p=>p.id));posts.value=older?[...posts.value,...data.items.filter(p=>!seen.has(p.id))]:data.items;hasMore.value=data.hasMore;before.value=data.nextBeforeId}catch(e){if(alive&&run===sequence)error.value=message(e)}finally{if(alive&&run===sequence)loading.value=false}}
function clearImage(id:string){const row=images.value.find(i=>i.id===id);if(row)URL.revokeObjectURL(row.url);images.value=images.value.filter(i=>i.id!==id)}
async function pick(event:Event){const files=Array.from((event.target as HTMLInputElement).files||[]);if(!files.length)return;if(images.value.length+files.length>9){ElMessage.warning('每条动态最多9张图片');return}const generation=epoch;uploading.value=true;for(const file of files){if(!alive||generation!==epoch)break;if(file.size>5*1024*1024){ElMessage.warning(`${file.name} 超过5MB`);continue}try{const image=await mediaApi.upload(file,'PRIVATE');if(alive&&generation===epoch)images.value.push({id:image.id,url:URL.createObjectURL(file)})}catch(e){if(alive&&generation===epoch)ElMessage.error(message(e))}}if(alive&&generation===epoch)uploading.value=false;if(fileInput.value)fileInput.value.value=''}
async function publish(){if(publishing.value||uploading.value)return;const content=draft.value.trim(),ids=images.value.map(i=>i.id);if(!content&&!ids.length)return;if([...content].length>2000){ElMessage.warning('动态最多2000字');return}if(retry?.content!==content||JSON.stringify(retry?.mediaIds)!==JSON.stringify(ids))retry={clientRequestId:crypto.randomUUID(),content,mediaIds:ids};publishing.value=true;try{const p=await communityApi.create(retry!);if(!alive)return;sequence++;loading.value=false;draft.value='';images.value.forEach(i=>URL.revokeObjectURL(i.url));images.value=[];retry=null;if(!authorId.value||own.value){posts.value=[p,...posts.value.filter(row=>row.id!==p.id)]}else await router.push('/wall');ElMessage.success('动态已发布')}catch(e){if(alive)ElMessage.error(message(e)+'；可点击发布重试')}finally{publishing.value=false}}
function updated(post:Post){posts.value=posts.value.map(p=>p.id===post.id?post:p)}
watch(authorId,async id=>{epoch++;sequence++;loading.value=false;uploading.value=false;posts.value=[];before.value=null;authorName.value='';void load();if(id){try{const profile=await socialApi.user(id);if(alive&&id===authorId.value)authorName.value=profile.nickname}catch(e){if(alive)error.value=message(e)}}},{immediate:true})
onBeforeUnmount(()=>{alive=false;epoch++;sequence++;images.value.forEach(i=>URL.revokeObjectURL(i.url))})
</script>
<template>
 <section class="wall-page">
  <header class="wall-heading"><div><span>把生活和喜欢，分享给同频的人</span><h1>{{title}} <small v-if="!authorId">WALL</small></h1></div><div class="feed-tabs"><el-button :type="!authorId?'primary':'default'" round @click="router.push('/wall')">全部动态</el-button><el-button :type="own?'primary':'default'" round @click="router.push({name:'wall',query:{authorId:auth.user?.id}})">我的动态</el-button></div></header>
  <div class="wall-layout"><div class="wall-feed">
   <section class="post-composer"><div class="compose-heading"><el-avatar :size="38" :src="auth.user?.avatar"/><strong>今天有什么想分享的？</strong></div><el-input v-model="draft" type="textarea" :rows="4" :maxlength="4000" :disabled="publishing" resize="none" placeholder="分享生活碎片、游戏高光，或约朋友下一局…"/><div v-if="images.length" class="upload-grid"><div v-for="image in images" :key="image.id"><img :src="image.url" alt="待发布图片"/><button :disabled="publishing" :aria-label="`移除图片 ${images.indexOf(image)+1}`" @click="clearImage(image.id)">×</button></div></div><div class="compose-footer"><el-button text :loading="uploading" :disabled="publishing||images.length>=9" @click="fileInput?.click()">▧ 添加图片 {{images.length}} / 9</el-button><input ref="fileInput" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden @change="pick"/><small>{{[...draft].length}} / 2000</small><el-button type="primary" :loading="publishing" :disabled="uploading||(!draft.trim()&&!images.length)" @click="publish">发布动态</el-button></div><p class="visibility-note">发布后，平台内所有已登录用户均可查看文字、图片与评论。</p></section>
   <div class="feed-tools"><span>{{authorId?'按发布时间排序':'最新动态 · 按发布时间排序'}}</span><el-button text :loading="loading" @click="load()">刷新动态</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><PostCard v-for="post in posts" :key="post.id" :post="post" @updated="updated" @removed="id=>posts=posts.filter(p=>p.id!==id)"/><div v-if="!posts.length&&!loading&&!error" class="wall-empty"><span>✦</span><h3>这里还很安静</h3><p>发一条动态，让朋友发现你的新鲜事。</p></div><div class="load-more"><el-button v-if="hasMore" :loading="loading" @click="load(true)">加载更多动态</el-button><span v-else-if="posts.length">已经看到全部动态了</span><span v-else-if="loading">正在加载动态…</span></div>
  </div><aside class="wall-aside"><div><span class="aside-moon">☾</span><h2>月亮知道你的心事</h2><p>一场有趣的对局，一张路上的照片，一句想说的话。把喜欢留在这里。</p><router-link to="/friends">去认识新朋友 →</router-link></div><div class="wall-tips"><strong>分享小提示</strong><p>支持文字、表情和最多9张图片。</p><p>图片每张不超过5MB，支持 JPEG、PNG、WebP。</p><p>自己的动态和评论可以删除，点赞也可以随时取消。</p></div></aside></div>
 </section>
</template>
<style scoped>
.wall-page{max-width:1100px;margin:14px auto 30px}.wall-heading{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:26px}.wall-heading>div>span{color:var(--ww-text-dim);font-size:12px}.wall-heading h1{font-size:30px;margin:10px 0 0}.wall-heading h1 small{font-size:12px;letter-spacing:3px;color:#c8a8db;margin-left:10px}.wall-layout{display:grid;grid-template-columns:minmax(0,730px) minmax(220px,1fr);gap:26px}.wall-feed{min-width:0}.post-composer{background:linear-gradient(130deg,rgba(68,42,83,.6),rgba(20,28,49,.9));border:1px solid rgba(190,136,218,.25);border-radius:18px;padding:22px}.compose-heading{display:flex;align-items:center;gap:12px;margin-bottom:16px;font-size:14px}.compose-footer{display:flex;align-items:center;gap:6px;margin-top:12px}.compose-footer small{margin-left:auto;color:var(--ww-text-dim);font-size:11px}.visibility-note{font-size:11px;color:var(--ww-text-dim);line-height:1.8;margin:12px 0 0}.upload-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:14px}.upload-grid>div{position:relative}.upload-grid img{display:block;width:100%;height:110px;object-fit:cover;border-radius:10px}.upload-grid button{position:absolute;top:4px;right:4px;border:0;background:#101626cc;color:white;border-radius:50%;width:24px;height:24px;cursor:pointer}.feed-tools{display:flex;justify-content:space-between;align-items:center;margin:14px 0;color:var(--ww-text-dim);font-size:12px}.wall-aside>div{border:1px solid var(--ww-border);border-radius:18px;padding:24px;margin-bottom:20px;background:rgba(26,28,48,.7)}.aside-moon{font-size:48px;color:#e0bf87}.wall-aside h2{font-size:18px;line-height:1.6}.wall-aside p{font-size:12px;color:var(--ww-text-dim);line-height:2}.wall-aside a{font-size:12px;color:#dbb5df;text-decoration:none}.wall-tips strong{font-size:14px}.load-more{text-align:center;font-size:12px;color:var(--ww-text-dim);padding:12px}.wall-empty{padding:48px 24px;text-align:center;color:var(--ww-text-dim)}.wall-empty>span{font-size:40px;color:#d6aad7}.wall-empty h3{font-size:18px}.wall-empty p{font-size:13px}
@media(max-width:850px){.wall-layout{grid-template-columns:minmax(0,1fr)}.wall-aside{display:none}}@media(max-width:680px){.wall-page{margin-top:8px}.wall-heading{align-items:flex-start;flex-direction:column;margin-bottom:18px}.wall-heading h1{font-size:26px}.wall-heading>div>span{font-size:11px}.post-composer{padding:16px 14px;border-radius:14px}.compose-footer small{display:none}.compose-footer>.el-button:last-child{margin-left:auto}.upload-grid img{height:85px}.feed-tabs{display:flex;gap:8px}.feed-tabs .el-button+.el-button{margin-left:0}}
